const items = $input.all();
const leads = (items[0] && items[0].json && Array.isArray(items[0].json.leads)) ? items[0].json.leads : [];

const total = leads.length;
const hotLeads = leads.filter(l => (l.score || l.qualificationScore || 0) >= 70);
const avgScore = total > 0 ? Math.round(leads.reduce((acc, cur) => acc + (cur.score || cur.qualificationScore || 0), 0) / total) : 0;

return [{
  json: {
    date: new Date().toISOString().split('T')[0],
    totalCount: total,
    hotCount: hotLeads.length,
    averageScore: avgScore,
    hotLeadsSummary: hotLeads.slice(0, 5).map(l => `${l.name} (${l.company || l.email}) - Score: ${l.score || l.qualificationScore}`)
  }
}];

const data = $input.item.json;
const hotList = data.hotLeadsSummary.length > 0 ? data.hotLeadsSummary.join('\n• ') : 'None in past 24h';
const text = `📊 *Daily Lead Rollup — ${data.date}*\n• *Total Inquiries:* ${data.totalCount}\n• *🔥 Hot Leads:* ${data.hotCount}\n• *Average Score:* ${data.averageScore}/100\n\n*Top Prospects:*\n• ${hotList}`;

return {
  json: {
    slackPayload: {
      text: `Daily Lead Rollup: ${data.totalCount} leads received (${data.hotCount} hot)`,
      attachments: [{
        color: '#36a64f',
        text: text,
        footer: 'AutomateStack Daily Digest'
      }]
    }
  }
};
